const mails = await api.get("/mails", { label: "환불" });
const customers = await api.get("/customers", { tier: "gold" });
const mArr = Array.isArray(mails) ? mails : (mails.items || mails.data || []);
const cArr = Array.isArray(customers) ? customers : (customers.items || customers.data || []);
console.log("mails top keys:", Object.keys(mails));
console.log("customers top keys:", Object.keys(customers));
if (mArr[0]) console.log("mail keys:", Object.keys(mArr[0]));
if (cArr[0]) console.log("customer keys:", Object.keys(cArr[0]));
console.log("mail count:", mArr.length, "gold count:", cArr.length);

const all = await api.get("/mails", {});
const arr = all.items || [];
console.log("total mails:", arr.length);
if (arr[0]) console.log("mail keys:", Object.keys(arr[0]));
const labels = {};
for (const m of arr) { const l = m.label; labels[l] = (labels[l] || 0) + 1; }
console.log("labels:", JSON.stringify(labels));

const refund = await api.get("/mails", { label: "refund" });
const refundIds = new Set((refund.items || []).map(m => m.customer_id));
const gold = await api.get("/customers", { tier: "gold" });
const matches = (gold.items || []).filter(c => refundIds.has(c.id)).map(c => c.name);
console.log("refund mails:", (refund.items || []).length, "gold customers:", (gold.items || []).length);
console.log("matches:", JSON.stringify(matches));

